				function getHeadings() {
					return [{"depth":2,"slug":"what-the-nonprofit-rate-actually-is","text":"What the Nonprofit Rate Actually Is"},{"depth":2,"slug":"who-qualifies","text":"Who Qualifies"},{"depth":2,"slug":"the-authorization-process","text":"The Authorization Process"},{"depth":2,"slug":"using-the-nonprofit-rate-through-a-mail-house","text":"Using the Nonprofit Rate Through a Mail House"},{"depth":2,"slug":"maintaining-your-nonprofit-authorization","text":"Maintaining Your Nonprofit Authorization"},{"depth":2,"slug":"nonprofit-rate-vs-eddm-an-important-distinction","text":"Nonprofit Rate vs. EDDM: An Important Distinction"},{"depth":2,"slug":"understanding-presort-levels-and-rate-tiers","text":"Understanding Presort Levels and Rate Tiers"},{"depth":2,"slug":"how-much-can-you-save-real-campaign-examples","text":"How Much Can You Save? Real Campaign Examples"},{"depth":2,"slug":"content-rules-for-nonprofit-rate-mailings","text":"Content Rules for Nonprofit Rate Mailings"},{"depth":2,"slug":"when-nonprofit-postage-doesnt-apply-alternatives","text":"When Nonprofit Postage Doesn’t Apply: Alternatives"}];
				}

